(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-506":{scenario:{company:"Kim Long Logistics JSC",supervisor:{name:"Phan Hoài Nam",role:{vi:"Người phụ trách quản trị công ty",en:"Head of Corporate Governance Office"}},ref_code:"AGM-2026",title:{vi:"Đúng ngưỡng biểu quyết. Đúng tỷ lệ dự họp. Đúng công bằng.",en:"Right voting threshold. Right quorum. Right fairness."},brief:{vi:"Đây là tình huống đào tạo. Bạn lập biên bản kiểm tra tư cách cổ đông cho cuộc họp ĐHĐCĐ thường niên lần thứ nhất, hồ sơ AGM-2026. Công ty phát hành 80000000 cổ phần phổ thông, trong đó 2500000 là cổ phiếu quỹ. Cổ đông dự họp trực tiếp, ủy quyền và bỏ phiếu điện tử sở hữu 39680000 cổ phần. Tờ trình thay đổi ngành, nghề kinh doanh ghi ngưỡng thông qua quá bán; Điều lệ không quy định khác. Hãy sửa ngưỡng thông qua và tỷ lệ dự họp.",en:"This is a training scenario. You are preparing the shareholder verification minutes for the first convening of the annual general meeting, file AGM-2026. The company has issued 80000000 ordinary shares, of which 2500000 are treasury shares. Shareholders attending in person, by proxy and by e-voting hold 39680000 shares. The proposal to change business lines states a simple majority; the charter says nothing different. Correct the approval threshold and the attendance ratio."},reference_title:{vi:"Điều lệ, quy chế họp & danh sách cổ đông đã chốt · AGM-2026",en:"Charter, meeting rules & shareholder record list · AGM-2026"},fields:[{id:"VOTE_RULE",label:{vi:"Ngưỡng thông qua tờ trình ngành nghề",en:"Approval threshold, business lines"},initial:"SIMPLE-50",expected:"SPECIAL-65",choices:["SIMPLE-50","SPECIAL-65","SPECIAL-75"],reference:"Luật Doanh nghiệp & Điều lệ công ty",hint:{vi:"Thay đổi ngành, nghề và lĩnh vực kinh doanh là nội dung cần đa số đặc biệt của cổ đông dự họp.",en:"Changing business lines and sectors requires a special majority of attending shareholders."}},{id:"QUORUM_PCT",label:{vi:"Tỷ lệ dự họp (%)",en:"Attendance ratio (%)"},initial:"49.60",expected:"51.20",reference:"Biên bản kiểm tra tư cách cổ đông",ref_value:{vi:"Phát hành 80000000 CP; cổ phiếu quỹ 2500000; dự họp 39680000 CP",en:"Issued 80000000 shares; treasury 2500000; attending 39680000 shares"},hint:{vi:"Cổ phiếu quỹ không có quyền biểu quyết nên không nằm trong mẫu số.",en:"Treasury shares carry no voting rights, so they are excluded from the denominator."}}],sop32:{vi:"Tỷ lệ dự họp (%) = cổ phần có quyền biểu quyết của cổ đông dự họp / tổng cổ phần có quyền biểu quyết (đã trừ cổ phiếu quỹ) x 100, làm tròn 2 chữ số thập phân; họp lần thứ nhất cần trên 50%.",en:"Attendance (%) = voting shares held by attending shareholders / total voting shares (excluding treasury shares) x 100, rounded to 2 decimals; a first convening needs more than 50%."},context:{label:"AGM PORTAL / AGM-2026",metrics:[{label:{vi:"Cổ phần đã phát hành",en:"Issued shares"},value:"80000000"},{label:{vi:"Cổ phiếu quỹ",en:"Treasury shares"},value:"2500000"},{label:{vi:"Cổ phần dự họp",en:"Shares attending"},value:"39680000"}]},crisis:{vi:"Một quỹ đầu tư lớn đề nghị bạn gửi trước số liệu lợi nhuận quý chưa công bố để “chuẩn bị bỏ phiếu”. Phó Tổng giám đốc nhắn: “Gửi riêng cho họ đi, quỹ thân thiết, đừng đăng lên website vội.”",en:"A large investment fund asks you for unpublished quarterly profit figures to “prepare its vote”. The Deputy CEO messages: “Send it to them privately, they are a friendly fund, don't post it on the website yet.”"},options:{safe:{vi:"Từ chối cung cấp thông tin chưa công bố cho riêng một cổ đông, báo Tổng giám đốc, Chủ tịch HĐQT và bộ phận tuân thủ, chỉ chia sẻ tài liệu đã công bố công khai cho mọi cổ đông cùng lúc.",en:"Refuse to give unpublished information to a single shareholder, inform the CEO, the Board Chair and compliance, and share only publicly disclosed materials with all shareholders at the same time."},shortcut:{vi:"Gửi số liệu qua email riêng vì quỹ cam kết giữ bí mật.",en:"Email the figures privately since the fund promises confidentiality."},wait:{vi:"Để quỹ chờ, không trả lời và không báo cáo ai.",en:"Leave the fund waiting, do not reply and report to no one."}},questions:{vi:["Vì sao tờ trình thay đổi ngành nghề cần ngưỡng SPECIAL-65 chứ không phải quá bán? Căn cứ nào trong luật và Điều lệ?","Trình bày cách tính tỷ lệ dự họp, ảnh hưởng của cổ phiếu quỹ và rủi ro pháp lý nếu cung cấp thông tin chưa công bố cho riêng một nhà đầu tư."],en:["Why does the business-line proposal need SPECIAL-65 rather than a simple majority? What is the legal and charter basis?","Explain how you calculated attendance, the effect of treasury shares and the legal risk of giving unpublished information to one investor."]},hints:{vi:["Đối chiếu nội dung tờ trình với danh mục vấn đề cần đa số đặc biệt trong luật và Điều lệ.","Trừ cổ phiếu quỹ khỏi tổng cổ phần trước khi chia theo SOP mục 3.2.","Đọc lại SOP mục 4.2: thông tin chưa công bố phải được giữ kín và công bố công bằng cho mọi nhà đầu tư."],en:["Match the proposal against the list of matters requiring a special majority in the law and charter.","Subtract treasury shares from total shares before dividing, as SOP 3.2 requires.","Re-read SOP 4.2: unpublished information must stay confidential and be disclosed fairly to all investors."]}},learning:{summary:{vi:"Thư ký Công ty & Quan hệ Nhà đầu tư bảo đảm HĐQT và ĐHĐCĐ vận hành đúng luật, Điều lệ: chuẩn bị họp, kiểm tra tư cách cổ đông, kiểm phiếu, lập biên bản, nghị quyết, công bố thông tin đúng hạn và là cầu nối minh bạch giữa doanh nghiệp với cổ đông, nhà đầu tư, cơ quan quản lý thị trường. Nghề đòi hỏi chính xác tuyệt đối, hiểu luật doanh nghiệp, chứng khoán và giữ bí mật thông tin nội bộ.",en:"A Corporate Secretary & Investor Relations officer makes sure the Board and the general meeting operate in line with the law and charter: preparing meetings, verifying shareholders, counting votes, writing minutes and resolutions, disclosing on time, and acting as a transparent bridge to shareholders, investors and market regulators. The role demands absolute accuracy, knowledge of corporate and securities law and protection of inside information."},responsibilities:{vi:["Lập kế hoạch, chốt danh sách cổ đông, gửi thông báo mời họp và tài liệu ĐHĐCĐ đúng hạn.","Kiểm tra tư cách cổ đông, tính tỷ lệ dự họp, tổ chức kiểm phiếu và lập biên bản.","Soạn nghị quyết, biên bản họp HĐQT, ĐHĐCĐ và theo dõi thực hiện.","Công bố thông tin định kỳ, bất thường theo quy định thị trường chứng khoán.","Trả lời câu hỏi nhà đầu tư, tổ chức gặp gỡ, họp công bố kết quả kinh doanh."],en:["Plan meetings, close the shareholder register and send AGM notices and materials on time.","Verify shareholders, compute attendance, run vote counting and write minutes.","Draft resolutions and Board and AGM minutes and track their implementation.","Make periodic and extraordinary disclosures under securities market rules.","Answer investor questions and organize investor meetings and earnings calls."]},competencies:[{name:{vi:"Quản trị cuộc họp",en:"Meeting governance"},desc:{vi:"Nắm thời hạn mời họp, điều kiện tiến hành, ngưỡng biểu quyết và thể thức lấy ý kiến bằng văn bản.",en:"Know notice periods, quorum conditions, voting thresholds and written ballot procedures."}},{name:{vi:"Kiểm phiếu chính xác",en:"Accurate vote counting"},desc:{vi:"Đối chiếu danh sách cổ đông, giấy ủy quyền, phiếu điện tử và loại trừ cổ phần không có quyền biểu quyết.",en:"Reconcile the register, proxies and e-votes and exclude shares without voting rights."}},{name:{vi:"Công bố thông tin",en:"Disclosure management"},desc:{vi:"Công bố đầy đủ, chính xác, đúng hạn và công bằng cho mọi nhà đầu tư.",en:"Disclose fully, accurately, on time and fairly to all investors."}},{name:{vi:"Truyền thông nhà đầu tư",en:"Investor communication"},desc:{vi:"Trình bày chiến lược, kết quả kinh doanh rõ ràng, nhất quán với tài liệu đã công bố.",en:"Present strategy and results clearly and consistently with published documents."}},{name:{vi:"Bảo mật thông tin nội bộ",en:"Inside information control"},desc:{vi:"Quản lý danh sách người nội bộ, thời gian cấm giao dịch và từ chối công bố chọn lọc.",en:"Manage insider lists and blackout periods and refuse selective disclosure."}}],knowledge:{vi:["Luật Doanh nghiệp 2020: Điều 143 mời họp ít nhất 21 ngày, Điều 145 điều kiện tiến hành họp, Điều 148 điều kiện thông qua nghị quyết.","Ngưỡng 65% cổ phần dự họp cho loại cổ phần, ngành nghề, cơ cấu quản lý, tổ chức lại, giải thể, trừ khi Điều lệ quy định khác.","Luật Chứng khoán 2019 (số 54/2019/QH14) và Nghị định 155/2020/NĐ-CP về quản trị công ty đại chúng.","Thông tư 96/2020/TT-BTC hướng dẫn công bố thông tin trên thị trường chứng khoán, gồm công bố bất thường trong 24 giờ.","Nguyên tắc đối xử công bằng với cổ đông và cấm giao dịch nội gián, công bố thông tin chọn lọc."],en:["Law on Enterprises 2020: Article 143 notice at least 21 days, Article 145 quorum conditions, Article 148 resolution approval conditions.","A 65% threshold of attending votes for share classes, business lines, management structure, reorganization and dissolution unless the charter says otherwise.","Law on Securities 2019 (No. 54/2019/QH14) and Decree 155/2020/ND-CP on corporate governance of public companies.","Circular 96/2020/TT-BTC on information disclosure in the securities market, including 24-hour extraordinary disclosure.","Equal treatment of shareholders and prohibitions on insider trading and selective disclosure."]},tools:["Nền tảng họp và bỏ phiếu điện tử","Danh sách cổ đông từ tổ chức lưu ký","Hệ thống công bố thông tin của sở giao dịch","Phần mềm kiểm phiếu","Website quan hệ nhà đầu tư"],kpis:{vi:["Tỷ lệ công bố thông tin đúng hạn (mục tiêu 100%).","Số nghị quyết bị yêu cầu hủy bỏ do sai trình tự, thủ tục (mục tiêu 0).","Thời gian phản hồi câu hỏi nhà đầu tư.","Tỷ lệ cổ đông tham dự và biểu quyết tại ĐHĐCĐ."],en:["On-time disclosure rate (target 100%).","Resolutions challenged for procedural errors (target zero).","Response time to investor questions.","Shareholder participation and voting rate at the AGM."]},day:[{time:"08:30",vi:"Rà lịch công bố thông tin, kiểm tra các sự kiện cần công bố trong 24 giờ.",en:"Review the disclosure calendar and check events requiring 24-hour disclosure."},{time:"10:00",vi:"Đối chiếu danh sách cổ đông với giấy ủy quyền và đăng ký bỏ phiếu điện tử.",en:"Reconcile the shareholder list with proxies and e-voting registrations."},{time:"13:30",vi:"Soạn tờ trình, dự thảo nghị quyết và kịch bản điều hành ĐHĐCĐ.",en:"Draft proposals, resolutions and the AGM chair's script."},{time:"15:30",vi:"Họp trực tuyến với nhà đầu tư tổ chức, chỉ dùng thông tin đã công bố.",en:"Hold an online meeting with institutional investors using only published information."},{time:"17:00",vi:"Cập nhật danh sách người nội bộ, lưu biên bản và nhật ký công bố.",en:"Update the insider list and archive minutes and the disclosure log."}],mistakes:{vi:["Tính tỷ lệ dự họp trên tổng cổ phần phát hành mà không trừ cổ phiếu quỹ.","Áp ngưỡng quá bán cho nội dung cần đa số đặc biệt, khiến nghị quyết có thể bị hủy.","Gửi thông tin chưa công bố cho riêng một nhà đầu tư hoặc chuyên gia phân tích."],en:["Computing attendance on total issued shares without excluding treasury shares.","Applying a simple majority to matters needing a special majority, exposing the resolution to annulment.","Sending unpublished information to a single investor or analyst."]},career:[{vi:"Chuyên viên văn phòng HĐQT",en:"Board office associate"},{vi:"Chuyên viên quan hệ nhà đầu tư",en:"Investor relations specialist"},{vi:"Thư ký công ty, người phụ trách quản trị",en:"Corporate secretary, governance officer"},{vi:"Giám đốc Quan hệ nhà đầu tư & Quản trị công ty",en:"Director of investor relations & governance"}],glossary:[{term:"Cổ phiếu quỹ",vi:"Cổ phần đã phát hành do chính công ty mua lại, không có quyền biểu quyết và không được chia cổ tức.",en:"Treasury shares: issued shares bought back by the company, with no voting or dividend rights."},{term:"Quorum",vi:"Điều kiện tiến hành họp: tỷ lệ phiếu biểu quyết tối thiểu của cổ đông dự họp theo luật và Điều lệ.",en:"The minimum share of votes held by attending shareholders needed to hold the meeting."},{term:"Ngày đăng ký cuối cùng",vi:"Ngày chốt danh sách cổ đông có quyền dự họp hoặc nhận quyền lợi.",en:"Record date: the date fixing the list of shareholders entitled to attend or receive benefits."},{term:"Công bố thông tin bất thường",vi:"Công bố sự kiện ảnh hưởng lớn tới giá chứng khoán hoặc quyền lợi nhà đầu tư trong thời hạn ngắn luật định.",en:"Extraordinary disclosure: publishing price-sensitive events within a short legal deadline."},{term:"Công bố chọn lọc",vi:"Cung cấp thông tin quan trọng chưa công khai cho một số người, gây bất bình đẳng giữa nhà đầu tư.",en:"Selective disclosure: giving material non-public information to some people, treating investors unequally."}],quiz:[{q:{vi:"Theo Luật Doanh nghiệp 2020, thông báo mời họp ĐHĐCĐ phải gửi cho cổ đông chậm nhất bao nhiêu ngày trước ngày khai mạc?",en:"Under the Law on Enterprises 2020, how many days before the meeting must the AGM notice be sent at the latest?"},options:{vi:["7 ngày","10 ngày","15 ngày","21 ngày"],en:["7 days","10 days","15 days","21 days"]},answer:3,explain:{vi:"Điều 143 quy định gửi thông báo mời họp ít nhất 21 ngày trước ngày khai mạc, trừ khi Điều lệ quy định dài hơn.",en:"Article 143 requires notice at least 21 days before the meeting unless the charter sets a longer period."}},{q:{vi:"Công ty có 50000000 cổ phần, 5000000 cổ phiếu quỹ; cổ đông dự họp sở hữu 22500000 cổ phần. Kết luận nào đúng với họp lần thứ nhất?",en:"A company has 50000000 shares, 5000000 in treasury; attending shareholders hold 22500000 shares. Which is right for a first convening?"},options:{vi:["50.00% - chưa đủ điều kiện tiến hành","45.00% - chưa đủ điều kiện","50.00% - đủ điều kiện tiến hành","55.00% - đủ điều kiện"],en:["50.00% - quorum not met","45.00% - quorum not met","50.00% - quorum met","55.00% - quorum met"]},answer:0,explain:{vi:"22500000 / 45000000 = 50.00%; luật yêu cầu trên 50% nên chưa đủ điều kiện họp lần thứ nhất.",en:"22500000 / 45000000 = 50.00%; the law requires more than 50%, so the quorum is not met."}},{q:{vi:"Một nhà phân tích xin trước số liệu lợi nhuận quý chưa công bố. Bạn làm gì?",en:"An analyst asks for unpublished quarterly profit figures in advance. What do you do?"},options:{vi:["Gửi vì họ cam kết bảo mật","Gửi bản ước tính thay số chính thức","Từ chối, chỉ dùng thông tin đã công bố và báo bộ phận tuân thủ","Gợi ý bằng lời qua điện thoại"],en:["Send it since they promise secrecy","Send an estimate instead of official figures","Refuse, use only published information and inform compliance","Hint at it verbally by phone"]},answer:2,explain:{vi:"Công bố chọn lọc vi phạm nguyên tắc công bằng và có thể tạo điều kiện giao dịch nội gián.",en:"Selective disclosure breaches fairness and can enable insider trading."}},{q:{vi:"Nội dung nào cần ngưỡng 65% phiếu biểu quyết của cổ đông dự họp khi Điều lệ không quy định khác?",en:"Which matter needs 65% of attending votes when the charter is silent?"},options:{vi:["Phương án phân phối lợi nhuận","Thay đổi ngành, nghề kinh doanh","Lựa chọn công ty kiểm toán","Thông qua báo cáo của HĐQT"],en:["Profit distribution plan","Change of business lines","Selection of the audit firm","Approval of the Board report"]},answer:1,explain:{vi:"Điều 148 liệt kê thay đổi ngành, nghề và lĩnh vực kinh doanh trong nhóm cần từ 65% trở lên.",en:"Article 148 lists changes of business lines and sectors among matters needing 65% or more."}}],tools_en:["Electronic meeting and e-voting platform","Shareholder list from the depository","Stock exchange disclosure system","Vote counting software","Investor relations website"]}}})})(window.KKR);
